'use client'

import { motion } from 'framer-motion'
import { Braces, Code2, Database, Workflow } from 'lucide-react'
import type { SkillCategory } from '../types'

const skillCategories: SkillCategory[] = [
  {
    id: 'frontend',
    title: 'Frontend',
    description: 'Interfaces that feel fast, clear, and a little delightful.',
    skills: [
      'React.js',
      'Next.js (App Router)',
      'TypeScript',
      'JavaScript (ES6+)',
      'Tailwind CSS',
      'DaisyUI',
      'HTML5',
      'CSS3',
    ],
  },
  {
    id: 'backend',
    title: 'Backend & Systems',
    description: 'Reliable foundations for useful, scalable products.',
    skills: ['Node.js', 'Express.js', 'Go (Golang APIs)', 'RESTful APIs'],
  },
  {
    id: 'data-auth',
    title: 'Database & Auth',
    description: 'Secure flows and practical data persistence.',
    skills: ['MongoDB', 'BetterAuth', 'JWT', 'LocalStorage APIs'],
  },
  {
    id: 'tools',
    title: 'Tools & Workflow',
    description: 'A thoughtful process from first commit to deploy.',
    skills: ['Git', 'GitHub', 'VS Code', 'Vite', 'Postman', 'Vercel', 'Netlify'],
  },
]

const categoryIcons = [Code2, Braces, Database, Workflow]

export default function Skills() {
  return (
    <section className="section-wrap section-block skills-section" id="skills">
      <motion.div
        className="section-heading"
        initial={{ opacity: 0, y: 22 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, amount: 0.15 }}
        transition={{ duration: 0.55 }}
      >
        <div>
          <p className="eyebrow"><span>02</span>MY TOOLKIT</p>
          <h2>The tools behind<br />the ideas.</h2>
        </div>
        <p className="section-copy">
          A growing set of tools I reach for to turn a blank canvas into something useful.
        </p>
      </motion.div>
      <div className="skills-grid">
        {skillCategories.map(({ id, title, description, skills }, index) => {
          const Icon = categoryIcons[index]
          return (
            <motion.article
              className="skill-card"
              key={id}
              initial={{ opacity: 0, y: 22 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, amount: 0.15 }}
              transition={{ duration: 0.5, delay: index * 0.07 }}
            >
              <div className="skill-card-head">
                <span className="skill-icon"><Icon size={19} /></span>
                <span className="skill-index">0{index + 1}</span>
              </div>
              <h3>{title}</h3>
              <p>{description}</p>
              <div className="skill-tags">
                {skills.map((skill) => <span key={skill}>{skill}</span>)}
              </div>
              <div className="skill-meter" aria-label={`${skills.length} technologies in ${title}`}>
                <span>STACK BREADTH <b>{skills.length}</b></span>
                <div><i style={{ width: `${(skills.length / 8) * 100}%` }} /></div>
              </div>
            </motion.article>
          )
        })}
      </div>
    </section>
  )
}
